entries[33736] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 3 Wasserkugeln umringt, die ihm 50 Mana alle 5 Sek. gewähren. Wenn der Zaubernde durch einen Nahkampf-, Distanz- oder Zauberangriff getroffen wird, werden bei ihm 204 Mana wiederhergestellt. Dies verbraucht eine Wasserkugel. Es wird jeweils nur eine Wasserkugel alle paar Sekunden aktiviert. Hält 10 Min. lang an. Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
