entries[33891] = { ["name"] = "Baum des Lebens", ["text"] = "28% von Grundmana\nSofort\nVerwandelt Euch in die Gestalt eines Baums des Lebens. In dieser Gestalt ist die erhaltene Heilung bei allen Gruppenmitgliedern im Umkreis von 45 Metern um 25% Eurer gesamten Willenskraft erhöht, Euer Bewegungstempo ist um 20% verringert und Ihr könnt nur 'Rasche Heilung', 'Anregen', 'Schnelligkeit der Natur', 'Wiedergeburt', 'Baumrinde', Gift aufhebende Zauber und Heilzauber, die über einen bestimmten Zeitraum wirken, benutzen. Die Manakosten dieser Zauber sind um 20% verringert.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von verwandlungs- und bewegungseinschränkenden Effekten." }
entries[33895] = { ["name"] = "Sprengladung aktivieren", ["text"] = "Wirken in 2 sek.\nErschafft eine Sprengladung." }
entries[33896] = { ["name"] = "Verzweifelte Verteidigung", ["text"] = "40 Meter Reichweite\nSofort\nDer Zaubernde wurzelt sich selbst fest, schirmt sich von allen Angriffen ab und wird mehr und mehr wütend, je länger er angegriffen wird. Jeder Schlag erhöht den Effekt der Wut." }
entries[33898] = { ["name"] = "Verzweifelte Wut", ["text"] = "Sofort\nErhöht das Angriffstempo des Zaubernden um 5% und den verursachten körperlichen Schaden um 10. Hält 2 Min. lang an." }
