entries[33907] = { ["name"] = "Dornen", ["text"] = "30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, 5 Naturschaden zufügen. Hält 10 Min. lang an." }
entries[33908] = { ["name"] = "Brennende Stacheln", ["text"] = "30 Meter Reichweite\nAus dem befreundeten Ziel sprießen Dornen, die jedem, der es schlägt, 5 Feuerschaden zufügen. Hält bis Abbruch lang an." }
entries[33909] = { ["name"] = "Großer Grüner", ["text"] = "Sofort\nErhöht den vom Zauberneden zugefügten körperlichen Schaden bis Abbruch lang um 10%." }
entries[33910] = { ["name"] = "Andere Heilen", ["text"] = "215 Mana 40 Meter Reichweite\nWirken in 4 sek.\nRuft heilige Magie herbei, um einen Verbündeten zu heilen." }
entries[33911] = { ["name"] = "Rüstung zerfetzen", ["text"] = "Nahkampfreichweite\nSofort\nHackt auf die Rüstung eines Gegners ein, verringert sie um 0 pro Anwendung von 'Rüstung zerreißen'. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
entries[33912] = { ["name"] = "Zerfetzen", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 15 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
entries[33913] = { ["name"] = "Seelenbrand", ["text"] = "40 Meter Reichweite\nSofort\nFügt einem Gegner 6 Sek. lang insgesamt 1500 Feuerschaden zu, hindert ihn daran, Zauber zu wirken, und verringert den von ihm zugefügten körperlichen Schaden um 50%." }
entries[33914] = { ["name"] = "Schattenschlag", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nSchlägt einen Gegner, fügt Waffenschaden plus 5 zu." }
entries[33915] = { ["name"] = "Entzug der Leere" }
entries[33916] = { ["name"] = "Entzug der Leere", ["text"] = "25 Mana\nWirken in 3 sek.\nEntzieht allen Gegnern im Umkreis von 10 Metern Gesundheit." }
entries[33917] = { ["name"] = "Zerfleischen", ["text"] = "100 Meter Reichweite\nSofort\nZerfleischt das Ziel und fügt Schaden zu. Das Ziel erleidet 12 Sek. lang zusätzlichen Schaden durch Blutungseffekte. Diese Fähigkeit kann in Katzen- und Terrorbärengestalt angewendet werden." }
entries[33918] = { ["name"] = "Kristallkanal" }
entries[33919] = { ["name"] = "Erdbeben", ["text"] = "Wirken in 1 sek. 6 sek. Abklingzeit\nFügt nahen Gegnern 919 bis 1181 körperlichen Schaden zu, betäubt sie 3 Sek. lang." }
entries[33923] = { ["name"] = "Überschallknall", ["text"] = "Wirken in 5 sek." }
entries[33924] = { ["name"] = "Furcht", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek.\nErfüllt einen Feind mit Furcht, woraufhin er bis zu 4 Sek. lang voller Schrecken flüchtet. Es kann immer nur jeweils ein einzelnes Ziel mit Furcht erfüllt werden." }
entries[33925] = { ["name"] = "Phantomstoß", ["text"] = "20 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe" }
entries[33926] = { ["name"] = "Elunes Berührung", ["text"] = "Sofort\nStellt 1 Mana wieder her." }
entries[33928] = { ["name"] = "Eintauchen des Sandwurms" }
entries[33929] = { ["name"] = "Elementartotem", ["text"] = "Sofort\nBeschwört ein Totem das einen Elementar herbeiruft, der 10 Min. lang Dinge tut." }
entries[33930] = { ["name"] = "Elementartotem" }
entries[33932] = { ["name"] = "Tunnel", ["text"] = "Wirken in 1.5 sek.\nTeleportiert den Zaubernden vorwärts, so lange nichts im Weg ist." }
entries[33933] = { ["name"] = "Druckwelle", ["text"] = "620 Mana\nSofort 30 sek. Abklingzeit\nEine Flammenwelle geht vom Zaubernden aus, fügt allen Feinden, die in diese hineingeraten, 616 bis 724 Feuerschaden zu und macht sie 6 Sek. lang benommen." }
entries[33937] = { ["name"] = "Einheiten der Phase 2 betäuben" }
entries[33938] = { ["name"] = "Pyroschlag", ["text"] = "500 Mana 35 Meter Reichweite\nWirken in 6 sek.\nSchleudert einen riesigen feurigen Felsen hinaus, der 939 bis 1191 Feuerschaden sowie zusätzlich 12 Sek. lang insgesamt 356 Feuerschaden verursacht." }
entries[33943] = { ["name"] = "Fluggestalt", ["text"] = "13% von Grundmana\nSofort\nVerwandelt Euch in eine Fluggestalt, erhöht Euer Bewegungstempo um 60% und ermöglicht es Euch, zu fliegen. Kann nur in der Scherbenwelt und nicht im Kampf angewendet werden.\n\nDer Akt des Gestaltwandelns befreit den Zaubernden von verwandlungs- und bewegungseinschränkenden Effekten." }
entries[33944] = { ["name"] = "Magie dämpfen", ["text"] = "600 Mana 30 Meter Reichweite\nSofort\nSchwächt gegen das anvisierte Gruppenmitglied gerichtete Magie ab, wobei der von Zaubern zugefügte Schaden um bis zu 120 und Heilzauber um bis zu 240 verringert werden. Hält 10 Min. lang an." }
entries[33946] = { ["name"] = "Magie verstärken", ["text"] = "600 Mana 30 Meter Reichweite\nSofort\nVerstärkt gegen das anvisierte Gruppenmitglied gerichtete Magie, wobei der von Zaubern zugefügte Schaden um bis zu 120 und Heilzauber um bis zu 240 erhöht werden. Hält 10 Min. lang an." }
