entries[33953] = { ["name"] = "Heilzaubertemposchmuck", ["text"] = "Eure direkten Heilzauber und Heilzauber, die über einen bestimmten Zeitraum wirken, haben eine Chance, die Zaubertempowertung 6 Sek. lang um 320 zu erhöhen.\n(Procchance: 10%, 45s Abklingzeit)" }
