entries[33956] = { ["name"] = "Traumzustand", ["text"] = "Stellt alle 5 Sek. Mana entsprechend 10% Eurer Intelligenz wieder her, sogar beim Wirken von Zaubern." }
entries[33957] = { ["name"] = "Wilde Zähigkeit", ["text"] = "Erhöht Eure Chance, Betäubungs- und Furchteffekten zu widerstehen, um 15%." }
entries[33958] = { ["name"] = "Raserei" }
entries[33959] = { ["name"] = "Arkane Explosion", ["text"] = "120 Mana\nWirken in 1.5 sek.\nLässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden Arkanschaden zu." }
entries[33960] = { ["name"] = "Gegenschlag", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Gegner 0 Schaden zu und stößt ihn zurück." }
entries[33961] = { ["name"] = "Zauberreflexion", ["text"] = "Sofort\nErhebt Euren Schild und reflektiert den nächsten auf Euch gewirkten Zauber. Hält 6 Sek. lang an." }
entries[33962] = { ["name"] = "Kräftigen", ["text"] = "Sofort\nVerringert erlittenen Schaden aller Magiearten um 5%." }
entries[33963] = { ["name"] = "Cannibalize Cosmetic" }
entries[33964] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an und verursacht 150% des normalen Waffenschadens. Zusätzlich stellen die nächsten 5 erfolgreichen Nahkampfangriffe 0 Gesundheit wieder her. Dieser Effekt hält 10 Sek. lang an." }
entries[33965] = { ["name"] = "Umsehen", ["text"] = "Sofort\nVerursacht, dass der Zaubernde sich 8 Sek. Sek. lang vorsichtig umsieht." }
entries[33966] = { ["name"] = "Mörderischen Schlammling beschwören", ["text"] = "Wirken in 3 sek.\nBeschwört einen Schlammlingverbündeten." }
entries[33967] = { ["name"] = "Donnerknall", ["text"] = "Sofort\nVerursacht 71 bis 79 Naturschaden bei in der Nähe befindlichen Feinden, erhöht die Zeit zwischen ihren Angriffen um 33% und verlangsamt ihr Bewegungstempo um 40%. Hält 10 Sek. lang an." }
entries[33968] = { ["name"] = "Ätzender Nebel", ["text"] = "Nahkampfreichweite\nWirken in 1 sek.\nFügt nahen Gegnern 20 Sek. lang alle 2 Sek. 25 Naturschaden zu." }
entries[33969] = { ["name"] = "Absaugender Blitz", ["text"] = "565 Mana 30 Meter Reichweite\nWirken in 3 sek.\nFügt dem Gegner 80 Schattenschaden zu. Der Zaubernde erhält 100% des verursachten Schadens in Gesundheit." }
entries[33970] = { ["name"] = "Woge", ["text"] = "40 Meter Reichweite\nSofort\nStürmt auf einen Gegner zu, fügt dem Ziel sowie jedem seiner in der Nähe befindlichen Verbündeten 100 Schaden zu und stößt sie alle zurück." }
entries[33971] = { ["name"] = "Weitreichender Sturmangriff", ["text"] = "8 - 40 Meter Reichweite\nSofort\nStürmt auf einen Gegner zu, fügt ihm und nahen Verbündeten normalen Schaden plus 100 zu und stößt alle zurück." }
entries[33972] = { ["name"] = "Feuerregen", ["text"] = "15 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nLässt einen Schmelzregen niedergehen, der alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. 12 Feuerschaden zufügt." }
entries[33973] = { ["name"] = "Wichtel beschwören", ["text"] = "Sofort\nBeschwört einen Wichtel, der den Zaubernden begleitet, bis er freigegeben wird." }
entries[33974] = { ["name"] = "Machtbrand", ["text"] = "10 Meter Reichweite\nWirken in 2.5 sek.\nTrifft einen Feind mit einem Antimachtblitz, der 284 bis 288 Mana entzieht. Für jeden vom Blitz verbrauchten Manapunkt erleidet das Ziel 1 Schaden." }
entries[33975] = { ["name"] = "Pyroschlag", ["text"] = "130 Mana 35 Meter Reichweite\nWirken in 6 sek.\nFügt einem Feind erst Feuerschaden und dann 12 Sek. lang alle 3 Sek. zusätzlichen Schaden zu." }
entries[33976] = { ["name"] = "Tier heilen", ["text"] = "20 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nHeilt Euer Tier pro Sekunde um 38 Gesundheit, während Ihr fokussiert. Hält 10 Sek. lang an." }
