entries[33978] = { ["name"] = "Seele des Blutenden Auges beschwören" }
entries[33980] = { ["name"] = "Anhänger vergraben", ["text"] = "10 Meter Reichweite\nWirken in 1 sek.\nVergräbt Weißborkes Anhänger nahe des Runensteines im versengten Hain, um die Erinnerung in Frieden zu betten." }
entries[33981] = { ["name"] = "Totenerweckung", ["text"] = "Sofort\nBeschwört ein Skelett am Ort einer nahen Leiche. Aus einer Leiche können nicht mehrere Skelette beschworen werden." }
