entries[34436] = { ["name"] = "Schattenexplosion", ["text"] = "380 Mana\nSofort\nErzeugt eine Energiewelle, die alle in der Nähe befindlichen Feinde zurückstößt, 1600 bis 2400 Schattenschaden zufügt und alle Bedrohung entfernt." }
entries[34437] = { ["name"] = "Todesmantel", ["text"] = "200 Mana 30 Meter Reichweite\nSofort\nVerursacht 1313 bis 1687 Schattenschaden und das betroffene Ziel läuft 3 Sek. lang voller Entsetzen davon. Der Zaubernde erhält 100% des verursachten Schadens in Gesundheit." }
entries[34438] = { ["name"] = "Instabiles Gebrechen", ["text"] = "400 Mana 30 Meter Reichweite\nSofort\nSchattenenergie zerstört langsam das Ziel, indem 18 Sek. lang insgesamt 1050 Schaden zugefügt werden. Sollte 'Instabiles Gebrechen' gebannt werden, verursacht es 1575 Schaden beim Bannenden und bringt diesen 5 Sek. lang zum Schweigen." }
