entries[34529] = { ["name"] = "Netherkettenhemd", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nUrschatten (20), Urluft (20), Gehärteter Adamantitbarren (6), Teufelsstahlbarren (4), Khoriumbarren (8)\nNetherkettenhemd\nWird beim Aufheben gebunden\nBrust Kette\n757 Rüstung\n+40 Ausdauer\n+18 Intelligenz\n\nRoter Sockel\nGelber Sockel\nBlauer Sockel\nSockelbonus: +4 Beweglichkeit\n\nHaltbarkeit 140 / 140\n70\nBenötigt Rüstungsschmied\nAnlegen: Erhöht die kritische Trefferwertung um 28.\nAnlegen: Erhöht die Angriffskraft um 40.\nAnlegen: Stellt alle 5 Sek. 7 Mana wieder her." }
entries[34530] = { ["name"] = "Kettenhemd des wirbelnden Nethers", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nNetherkettenhemd , Urnether (10), Urmana (10)\nKettenhemd des wirbelnden Nethers\nWird beim Aufheben gebunden\nBrust Kette\n893 Rüstung\n+48 Ausdauer\n+22 Intelligenz\n\nRoter Sockel\nGelber Sockel\nBlauer Sockel\nSockelbonus: +4 Beweglichkeit\n\nHaltbarkeit 140 / 140\n70\nBenötigt Rüstungsschmied\nAnlegen: Erhöht die kritische Trefferwertung um 33.\nAnlegen: Erhöht die Angriffskraft um 68.\nAnlegen: Stellt alle 5 Sek. 9 Mana wieder her.\nBenutzen: Ihr seid 6 Sek. lang vor allen körperlichen Attacken geschützt, könnt aber nicht angreifen oder körperliche Fähigkeiten verwenden. (30 Min Abklingzeit)" }
entries[34533] = { ["name"] = "Brustplatte der Könige", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nUrmacht (8), Gehärteter Adamantitbarren (6), Eterniumbarren (6), Khoriumbarren (8)\nBrustplatte der Könige\nWird beim Aufheben gebunden\nBrust Platte\n1353 Rüstung\n+31 Stärke\n+46 Ausdauer\n\nBlauer Sockel\nGelber Sockel\nGelber Sockel\nSockelbonus: +4 Kritische Trefferwertung\n\nHaltbarkeit 165 / 165\n70\nBenötigt Rüstungsschmied\nAnlegen: Erhöht die Trefferwertung um 20.\nAnlegen: Erhöht die kritische Trefferwertung um 31." }
entries[34534] = { ["name"] = "Bollwerk der Könige", ["text"] = "Wirken in 50 sek.\nTools: Schmiedehammer\nReagenzien:\nBrustplatte der Könige , Urnether (10), Urmana (10)\nBollwerk der Könige\nWird beim Aufheben gebunden\nBrust Platte\n1595 Rüstung\n+35 Stärke\n+55 Ausdauer\n\nBlauer Sockel\nGelber Sockel\nGelber Sockel\nSockelbonus: +4 Kritische Trefferwertung\n\nHaltbarkeit 165 / 165\n70\nBenötigt Rüstungsschmied\nAnlegen: Erhöht die Trefferwertung um 23.\nAnlegen: Erhöht die kritische Trefferwertung um 37.\nBenutzen: Erhöht 15 Sek. lang Gesundheit um 1500 und Stärke um 150. (30 Min Abklingzeit)" }
